import{z as A,x as B,o as E,c as p,q as l,j as n,D as t,d as r,s as i,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"持久化与路径复制","description":"","frontmatter":{"title":"持久化与路径复制","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/persistent-path-copy.md","filePath":"cs/persistent-path-copy.md","lastUpdated":1791413859000}'),d={name:"cs/persistent-path-copy.md"};function h(m,a,c,u,D,f){const s=B("Mermaid");return E(),p("div",null,[a[2]||(a[2]=l('<h1 id="持久化与路径复制" tabindex="-1">持久化与路径复制 <a class="header-anchor" href="#持久化与路径复制" aria-label="Permalink to &quot;持久化与路径复制&quot;">​</a></h1><div class="epigraph"><p>更新不覆盖旧节点：复制根到修改点的路径，其余子树指针共享。旧根仍是完整的旧版本。</p><footer>—— 据 Driscoll, Sarnak, Sleator and Tarjan, Making Data Structures Persistent, JCSS 1989；Okasaki, Purely Functional Data Structures 整理</footer></div><p><a href="/cs/t-digest-quantile">上一课</a> 收束近似摘要。<a href="/cs/persistent-segment-tree">可持久化线段树</a> 已在区间树上做过一遍；<a href="/cs/hamt">HAMT</a> 与 <a href="/cs/rope-structure">Rope</a> 也用了共享。本课把方法从特例抽出来：部分持久 / 完全持久 / 函数式，以及路径复制的代价。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>版本控制、回溯、函数式语义要「改完仍能读旧」。fat node 在节点里存时间线，完全持久强、实现烦。路径复制：树（或 DAG 指针结构）每次更新 \\(\\Theta(h)\\) 新节点。缺口是<strong>一般树结构的版本 = 根指针</strong>，以及何时必须 fat node（有向图入度大、路径不唯一）。</p><p><span class="marginnote">术语翻译：这里的「持久化」不是存硬盘，而是数据结构每次修改都留下可读的历史版本——一个版本就是某个时刻的根指针。它来自半持久/全持久这套理论定义，与数据库的 durability 不是一回事。</span></p><p><span class="marginnote">Driscoll et al., <em>JCSS</em>, 1989。Okasaki 强调惰性与摊还在函数式堆/队列上的用法。本课先命令式复制，惰性下一课队列再用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>只读操作沿当前根，不写。写入：自叶向上 <code>new</code>，孩子指针指向旧或新。几何树、BST、线段树同一套路。可并堆破坏性 meld 会弄丢旧堆；函数式 meld 复制路径，接<a href="/cs/mergeable-heap">可并堆</a> 合同但表示不同。</p>',9)),(E(),n(o,null,{default:t(()=>[i(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20OLD%5B%22%E6%97%A7%E6%A0%B9%22%5D%20--%3E%20SH%5B%22%E5%85%B1%E4%BA%AB%E5%AD%90%E6%A0%91%22%5D%0A%20%20NEW%5B%22%E6%96%B0%E6%A0%B9%22%5D%20--%3E%20PATH%5B%22%E5%A4%8D%E5%88%B6%E7%9A%84%20O(h)%20%E8%8A%82%E7%82%B9%22%5D%0A%20%20PATH%20--%3E%20SH%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"空间：\\(m\\) 次更新 \\(O(m h)\\)。不要原地改已共享节点。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：路径复制像一次 Git 提交——只把改动经过的路径复制出新副本，其余子树指回旧版本；旧提交完好无损，随时可以「checkout」回去读。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"引用计数或 GC 回收无根可达的版本。多版本并发控制在数据库里同构，本课只钉内存结构。并发写同一逻辑树需 CAS 根或后课无锁，路径复制本身不解决线性化。",-1)),(E(),n(o,null,{default:t(()=>[i(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20PCOPY%5B%22%E8%B7%AF%E5%BE%84%E5%A4%8D%E5%88%B6%22%5D%0A%20%20%20%20A1%5B%22%E6%9B%B4%E6%96%B0%E5%A4%8D%E5%88%B6%E6%A0%B9%E5%88%B0%E4%BF%AE%E6%94%B9%E7%82%B9%E7%9A%84%E6%95%B4%E6%9D%A1%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20A2%5B%22%E6%97%A7%E7%89%88%E6%9C%AC%E7%BB%8F%E6%97%A7%E6%A0%B9%E5%AE%8C%E6%95%B4%E5%8F%AF%E8%AF%BB%22%5D%0A%20%20%20%20A2%20--%3E%20A3%5B%22%E4%BB%A3%E4%BB%B7%3A%20%E6%AF%8F%E6%AC%A1%20O(h)%20%E4%B8%AA%E6%96%B0%E8%8A%82%E7%82%B9%22%5D%0A%20%20end%0A%20%20subgraph%20FNOD%5B%22fat%20node%22%5D%0A%20%20%20%20B1%5B%22%E8%8A%82%E7%82%B9%E5%8E%9F%E5%9C%B0%E5%AD%98%E5%A4%9A%E6%9D%A1%E6%97%B6%E9%97%B4%E7%BA%BF%22%5D%20--%3E%20B2%5B%22%E8%AF%BB%E6%97%B6%E6%8C%89%E7%89%88%E6%9C%AC%E6%8C%91%E5%AD%97%E6%AE%B5%22%5D%0A%20%20%20%20B2%20--%3E%20B3%5B%22%E7%9C%81%E7%A9%BA%E9%97%B4%2C%20%E4%BD%86%E5%AE%9E%E7%8E%B0%E7%83%A6%E3%80%81%E5%9B%BE%E4%B8%8A%E5%85%A5%E5%BA%A6%E9%9A%BE%E5%8A%9E%22%5D%0A%20%20end%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p>缓存无关布局再下一课换的是扫描顺序，与版本正交；但可组合。</p><p><span class="marginnote">为什么重要：一旦有人原地改了共享节点，所有引用它的旧版本同时被污染，而且往往无从排查。纪律就一条——共享的只读：要改先 new 出副本；这条守不住，「持久化」就只剩个名字。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把全部 DSST 动态树持久化写完。图结构共享比树难。函数式 FIFO 有「倒栈」技巧，下一课专收，避免在这里把队列摊还证完。</p><p>后课默认：树的不可变更新用路径复制。函数式队列用双栈。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>路径复制：新版本 \\(O(h)\\) 节点，旧根只读。</li><li>共享子树；禁止写共享节点。</li><li>下一课把该方法用在 FIFO 上。</li><li>出处：Driscoll et al., <em>JCSS</em>, 1989；Okasaki。</li></ul>',7))])}const T=A(d,[["render",h]]);export{C as __pageData,T as default};
